 CREATE FUNCTION project_company_state() RETURNS trigger LANGUAGE plpgsql SET search_path=sica,pg_catalog AS $body$ BEGIN DELETE FROM rel_entry_lines WHERE company_id=NEW.id;
DELETE FROM rel_document_allocations WHERE company_id=NEW.id;
DELETE FROM rel_document_payments WHERE company_id=NEW.id;
DELETE FROM rel_document_lines WHERE company_id=NEW.id;
DELETE FROM rel_entries WHERE company_id=NEW.id;
DELETE FROM rel_treasury_moves WHERE company_id=NEW.id;
DELETE FROM rel_stock_moves WHERE company_id=NEW.id;
DELETE FROM rel_documents WHERE company_id=NEW.id;
DELETE FROM rel_products WHERE company_id=NEW.id;
DELETE FROM rel_parties WHERE company_id=NEW.id;
DELETE FROM rel_treasury_accounts WHERE company_id=NEW.id;
DELETE FROM rel_deposits WHERE company_id=NEW.id;
DELETE FROM rel_accounts WHERE company_id=NEW.id;
DELETE FROM rel_branches WHERE company_id=NEW.id;
INSERT INTO rel_branches(company_id,position,id,data) SELECT NEW.id,(j.ordinality-1)::integer,j.value->>'id',j.value FROM json_array_elements(NEW.state::json #> '{masters,branches}') WITH ORDINALITY j(value,ordinality);
INSERT INTO rel_accounts(company_id,position,id,data) SELECT NEW.id,(j.ordinality-1)::integer,j.value->>'id',j.value FROM json_array_elements(NEW.state::json #> '{masters,accounts}') WITH ORDINALITY j(value,ordinality);
INSERT INTO rel_deposits(company_id,position,id,data) SELECT NEW.id,(j.ordinality-1)::integer,j.value->>'id',j.value FROM json_array_elements(NEW.state::json #> '{masters,deposits}') WITH ORDINALITY j(value,ordinality);
INSERT INTO rel_treasury_accounts(company_id,position,id,data) SELECT NEW.id,(j.ordinality-1)::integer,j.value->>'id',j.value FROM json_array_elements(NEW.state::json #> '{masters,treasury}') WITH ORDINALITY j(value,ordinality);
INSERT INTO rel_parties(company_id,position,id,data) SELECT NEW.id,(j.ordinality-1)::integer,j.value->>'id',j.value FROM json_array_elements(NEW.state::json #> '{parties}') WITH ORDINALITY j(value,ordinality);
INSERT INTO rel_products(company_id,position,id,data) SELECT NEW.id,(j.ordinality-1)::integer,j.value->>'id',j.value FROM json_array_elements(NEW.state::json #> '{products}') WITH ORDINALITY j(value,ordinality);
INSERT INTO rel_documents(company_id,position,id,data) SELECT NEW.id,(j.ordinality-1)::integer,j.value->>'id',j.value FROM json_array_elements(NEW.state::json #> '{documents}') WITH ORDINALITY j(value,ordinality);
INSERT INTO rel_stock_moves(company_id,position,id,data) SELECT NEW.id,(j.ordinality-1)::integer,j.value->>'id',j.value FROM json_array_elements(NEW.state::json #> '{stockMoves}') WITH ORDINALITY j(value,ordinality);
INSERT INTO rel_treasury_moves(company_id,position,id,data) SELECT NEW.id,(j.ordinality-1)::integer,j.value->>'id',j.value FROM json_array_elements(NEW.state::json #> '{treasuryMoves}') WITH ORDINALITY j(value,ordinality);
INSERT INTO rel_entries(company_id,position,id,data) SELECT NEW.id,(j.ordinality-1)::integer,j.value->>'id',j.value FROM json_array_elements(NEW.state::json #> '{entries}') WITH ORDINALITY j(value,ordinality);
INSERT INTO rel_document_lines(company_id,parent_id,position,data) SELECT NEW.id,p.id,(j.ordinality-1)::integer,j.value FROM rel_documents p CROSS JOIN LATERAL json_array_elements(p.data->'lines') WITH ORDINALITY j(value,ordinality) WHERE p.company_id=NEW.id;
INSERT INTO rel_document_payments(company_id,parent_id,position,data) SELECT NEW.id,p.id,(j.ordinality-1)::integer,j.value FROM rel_documents p CROSS JOIN LATERAL json_array_elements(p.data->'payments') WITH ORDINALITY j(value,ordinality) WHERE p.company_id=NEW.id;
INSERT INTO rel_document_allocations(company_id,parent_id,position,data) SELECT NEW.id,p.id,(j.ordinality-1)::integer,j.value FROM rel_documents p CROSS JOIN LATERAL json_array_elements(p.data->'allocations') WITH ORDINALITY j(value,ordinality) WHERE p.company_id=NEW.id;
INSERT INTO rel_entry_lines(company_id,parent_id,position,data) SELECT NEW.id,p.id,(j.ordinality-1)::integer,j.value FROM rel_entries p CROSS JOIN LATERAL json_array_elements(p.data->'lines') WITH ORDINALITY j(value,ordinality) WHERE p.company_id=NEW.id; RETURN NEW; END $body$;
